// Previous year .. two years ahead: enough for planning, small enough that
// calendar apps refresh quickly.
export function icsYears(currentYear) {
  return [currentYear - 1, currentYear, currentYear + 1, currentYear + 2];
}

const pad = (n) => String(n).padStart(2, "0");
const icsDate = (d) => `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}`;

export function escapeIcsText(s) {
  return String(s)
    .replace(/\\/g, "\\\\")
    .replace(/;/g, "\\;")
    .replace(/,/g, "\\,")
    .replace(/\r?\n/g, "\\n");
}

// Fold one content line at 75 octets without splitting a UTF-8 sequence.
export function foldIcsLine(line) {
  const enc = new TextEncoder();
  if (enc.encode(line).length <= 75) return line;
  const parts = [];
  let current = "";
  let bytes = 0;
  let limit = 75;
  for (const ch of line) {
    const len = enc.encode(ch).length;
    if (bytes + len > limit) {
      parts.push(current);
      current = "";
      bytes = 0;
      limit = 74; // continuation lines start with a space
    }
    current += ch;
    bytes += len;
  }
  parts.push(current);
  return parts.join("\r\n ");
}

function allDayEvent({ uid, date, summary, description, url }, stamp) {
  const next = new Date(date);
  next.setDate(next.getDate() + 1);
  return [
    "BEGIN:VEVENT",
    `UID:${uid}`,
    `DTSTAMP:${stamp}`,
    `DTSTART;VALUE=DATE:${icsDate(date)}`,
    `DTEND;VALUE=DATE:${icsDate(next)}`,
    `SUMMARY:${escapeIcsText(summary)}`,
    ...(description ? [`DESCRIPTION:${escapeIcsText(description)}`] : []),
    ...(url ? [`URL:${url}`] : []),
    "TRANSP:TRANSPARENT",
    "END:VEVENT",
  ];
}

export function buildIcs({ calName, calDesc, events, stamp }) {
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//Viikko Nro//viikkonro.fi//FI",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    `X-WR-CALNAME:${escapeIcsText(calName)}`,
    `X-WR-CALDESC:${escapeIcsText(calDesc)}`,
    "X-WR-TIMEZONE:Europe/Helsinki",
    "REFRESH-INTERVAL;VALUE=DURATION:P1D",
    "X-PUBLISHED-TTL:P1D",
    ...events.flatMap((e) => allDayEvent(e, stamp)),
    "END:VCALENDAR",
  ];
  return lines.map(foldIcsLine).join("\r\n") + "\r\n";
}

// `inRange(year)` decides whether a page URL for that year exists, so a feed
// never links a page that would 404.
export function weekEvents(years, siteUrl, inRange) {
  return years.flatMap((y) =>
    Array.from({ length: weeksInIsoYear(y) }, (_, i) => {
      const w = i + 1;
      const mo = mondayOf(w, y);
      const su = new Date(mo);
      su.setDate(mo.getDate() + 6);
      return {
        uid: `viikko-${w}-${y}@viikkonro.fi`,
        date: mo,
        summary: `Vk ${w}`,
        description: `Viikko ${w}/${y}: ${fmtShortFi(mo)}–${fmtShortFi(su)}`,
        url: inRange(y) ? `${siteUrl}/viikko-${w}-${y}` : null,
      };
    }),
  );
}

export function holidayEvents(years, siteUrl) {
  return years.flatMap((y) =>
    holidaysInYear(y).map((h) => {
      const path = holidayLinkPath(h.name, h.date);
      return {
        uid: `pyha-${icsDate(h.date)}-${encodeURIComponent(h.name)}@viikkonro.fi`,
        date: h.date,
        summary: h.name,
        description: h.official
          ? "Virallinen arkipyhä Suomessa."
          : "Ei virallinen arkipyhä, mutta laajalti vapaapäivä. Pankit ovat kiinni.",
        url: path ? `${siteUrl}${path}` : null,
      };
    }),
  );
}

export function flagDayEvents(years, siteUrl, inRange) {
  return years.flatMap((y) =>
    flagDaysInYear(y).map((f) => ({
      uid: `liputus-${icsDate(f.date)}-${f.slug}@viikkonro.fi`,
      date: f.date,
      summary: `${f.name} (liputuspäivä)`,
      description: f.categoryLabel,
      url: inRange(y) ? `${siteUrl}/liputuspaivat-${y}#${f.slug}` : null,
    })),
  );
}

